#include "media.h"
#include "vga.h"
static u16 r16(const u8*p){return (u16)(p[0]|((u16)p[1]<<8));}static u32 r32(const u8*p){return (u32)p[0]|((u32)p[1]<<8)|((u32)p[2]<<16)|((u32)p[3]<<24);}static int eq4(const u8*p,const char*s){return p[0]==s[0]&&p[1]==s[1]&&p[2]==s[2]&&p[3]==s[3];}
typedef struct{int w,h,bpp,top;u32 comp;} AI;
static int info(const u8*d,u32 sz,AI*i){if(!d||sz<64||!eq4(d,"RIFF")||!eq4(d+8,"AVI "))return 0;for(u32 p=12;p+48<sz;p++){if(eq4(d+p,"strf")){u32 n=r32(d+p+4);if(n>=40&&p+8+n<=sz){const u8*b=d+p+8;i32 w=(i32)r32(b+4),h=(i32)r32(b+8);u16 bpp=r16(b+14);u32 c=r32(b+16);if(w>0&&h!=0&&(bpp==24||bpp==32)&&c==0){i->w=w;i->top=h<0;i->h=h<0?-h:h;i->bpp=bpp;i->comp=c;return 1;}}}}return 0;}
int avi_frame_count(const u8*d,u32 sz){AI i;if(!info(d,sz,&i))return 0;int n=0;for(u32 p=12;p+8<sz;p++){if(eq4(d+p,"00db")||eq4(d+p,"00dc")){u32 len=r32(d+p+4);if(p+8+len<=sz){n++;p+=7+((len+1)&~1u);}}}return n;}
int avi_draw_frame(const u8*d,u32 sz,int want,int cx,int cy,int cw,int ch){AI i;if(!info(d,sz,&i)||!vga_framebuffer())return 0;const u8*fr=0;u32 flen=0;int n=0;for(u32 p=12;p+8<sz;p++){if(eq4(d+p,"00db")||eq4(d+p,"00dc")){u32 len=r32(d+p+4);if(p+8+len<=sz){if(n==want){fr=d+p+8;flen=len;break;}n++;p+=7+((len+1)&~1u);}}}if(!fr)return 0;u32 row=((u32)i.w*(u32)(i.bpp/8)+3)&~3u;if(row*(u32)i.h>flen)return 0;int x,y,tw,th;vga_cell_rect(cx,cy,cw,ch,&x,&y,&tw,&th);vga_fill_px(x,y,tw,th,vga_rgb_bg());for(int yy=0;yy<th;yy++){int sy=(int)((u32)yy*(u32)i.h/(u32)th);if(!i.top)sy=i.h-1-sy;const u8*r=fr+(u32)sy*row;for(int xx=0;xx<tw;xx++){int sx=(int)((u32)xx*(u32)i.w/(u32)tw);const u8*p=r+(u32)sx*(i.bpp/8);u32 rgb=((u32)p[2]<<16)|((u32)p[1]<<8)|p[0];vga_pixel(x+xx,y+yy,rgb);}}return 1;}
